import React, { useState, useEffect, useRef } from 'react';

function SeriesAIChatbot() {
  const [messages, setMessages] = useState([
    {
      type: 'bot',
      content: 'Merhaba! Size dizi önerilerinde bulunabilirim. Hangi tür diziler ilginizi çekiyor?'
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { type: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      // Hugging Face API'sine istek at
      const response = await fetch(
        "https://api-inference.huggingface.co/models/microsoft/DialoGPT-medium",
        {
          headers: { 
            Authorization: "Bearer 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",
            "Content-Type": "application/json"
          },
          method: "POST",
          mode: 'cors',
          credentials: 'omit',
          body: JSON.stringify({ 
            inputs: `Sen bir dizi öneri asistanısın. Kullanıcıya dizi önerilerinde bulunuyorsun. Kullanıcının mesajı: ${userMessage}` 
          }),
        }
      );
      
      if (!response.ok) {
        throw new Error('API yanıt vermedi');
      }

      const result = await response.json();
      const botResponse = result[0]?.generated_text || "Üzgünüm, şu anda öneri sunamıyorum. Lütfen tekrar deneyin.";
      
      setMessages(prev => [...prev, { type: 'bot', content: botResponse }]);
    } catch (error) {
      console.error('API hatası:', error);
      setMessages(prev => [...prev, { 
        type: 'bot', 
        content: "Üzgünüm, bir hata oluştu. Lütfen tekrar deneyin." 
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-4 h-[600px] flex flex-col">
      <h2 className="text-xl font-bold mb-4 text-purple-600">Dizi Öneri Asistanı</h2>
      
      <div className="flex-1 overflow-y-auto mb-4 space-y-4">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] rounded-lg p-3 ${
                message.type === 'user'
                  ? 'bg-purple-500 text-white'
                  : 'bg-gray-100 text-gray-800'
              }`}
            >
              {message.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-gray-100 rounded-lg p-3 text-gray-800">
              Düşünüyorum...
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="flex gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Dizi önerisi isteyin..."
          className="flex-1 p-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
        />
        <button
          type="submit"
          disabled={isLoading}
          className="bg-purple-500 text-white px-4 py-2 rounded-lg hover:bg-purple-600 transition-colors disabled:opacity-50"
        >
          Gönder
        </button>
      </form>
    </div>
  );
}

export default SeriesAIChatbot;
